    def comp_of(p):
        st=[p];seen={p};cells=[]
        while st:
            a,b=st.pop();cells.append((a,b,g[a][b]))
            for di in(-1,0,1):
                for dj in(-1,0,1):
                    x,y=a+di,b+dj
                    if 0<=x<H and 0<=y<W and g[x][y] and (x,y) not in seen:
                        seen.add((x,y));st.append((x,y))
        return cells
